def maximumNumberPossible(s: str, k: int) -> str:
    arr = list(s)
    non5 = sum(1 for c in arr if c != '5')
    if k > non5:
        return "IMPOSSIBLE"
    # 第一轮：从左到右把 < 5 的数位改成 5，越靠左收益越大
    for i in range(len(arr)):
        if k == 0: break
        if arr[i] != '5' and arr[i] < '5':
            arr[i] = '5'
            k -= 1
    # 第二轮：剩余次数只能把 > 5 的数位改小，从最低位开始损失最小
    for i in range(len(arr) - 1, -1, -1):
        if k == 0: break
        if arr[i] != '5':
            arr[i] = '5'
            k -= 1
    return ''.join(arr)

if __name__ == "__main__":
    assert maximumNumberPossible("1839559", 4) == "5855555"
    assert maximumNumberPossible("5567855", 4) == "IMPOSSIBLE"
    assert maximumNumberPossible("165232", 3) == "565552"
    print("ok")

class Solution {
    String maximumNumberPossible(String s, int k) {
        char[] arr = s.toCharArray();
        int non5 = 0;
        for (char c : arr) if (c != '5') non5++;
        if (k > non5) return "IMPOSSIBLE";
        for (int i = 0; i < arr.length && k > 0; i++) {
            if (arr[i] != '5' && arr[i] < '5') { arr[i] = '5'; k--; }
        }
        for (int i = arr.length - 1; i >= 0 && k > 0; i--) {
            if (arr[i] != '5') { arr[i] = '5'; k--; }
        }
        return new String(arr);
    }
}

